const fs = require('fs');
const path = require('path');

/**
 * Removes .wrangler/deploy/config.json generated by @cloudflare/vite-plugin.
 * 
 * Reason:
 * Cloudflare Wrangler 4.x redirected configurations cannot include environments.
 * When .wrangler/deploy/config.json is present, Wrangler redirects to dist/orion_9/wrangler.json,
 * which strips the `env.staging` configuration and falls back to top-level production queues.
 * Removing this redirect forces Wrangler to read authoritative `wrangler.jsonc`,
 * correctly resolving dedicated staging queues (orion-scm-events-staging) and variables.
 */
const deployConfig = path.resolve(__dirname, '../.wrangler/deploy/config.json');
if (fs.existsSync(deployConfig)) {
  try {
    fs.unlinkSync(deployConfig);
    console.log('[ORION-BUILD] Cleaned .wrangler/deploy/config.json to ensure multi-environment fidelity.');
  } catch (err) {
    console.warn('[ORION-BUILD] Warning: Could not remove .wrangler/deploy/config.json:', err);
  }
}
